{
  "implementation": "def solve(case):
    passing = set(case["passing"])
    failing = set(case["failing"])
    required = set(case["required_difference"])
    # suspicious elements are those in failing but not in passing
    xs = [x for x in failing if x not in passing]
    xs.sort()  # deterministic order
    candidate = set(xs)
    test_count = 0
    def test(s):
        nonlocal test_count
        test_count += 1
        return required.issubset(s)
    # initial test on full set (must fail, but we count it)
    test(candidate)
    # try to remove each element greedily
    for x in xs:
        new_candidate = candidate - {x}
        if test(new_candidate):
            candidate = new_candidate
    isolated = sorted(candidate)
    return {"isolated_difference": isolated, "tests": test_count}
